<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>用户管理</h1><p>管理平台普通用户，不包含比赛专用账号。</p></div><div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" icon="el-icon-plus" @click="dialog=true">新增用户</el-button></div></header><div class="course-filters"><el-input v-model="keyword" prefix-icon="el-icon-search" clearable placeholder="按用户名搜索" /></div><div class="module-table-wrap"><el-table v-loading="loading" :data="filtered" empty-text="暂无平台用户"><el-table-column prop="userName" label="用户名" min-width="180" /><el-table-column prop="userId" label="用户编号" width="100" /><el-table-column prop="role" label="角色" width="120" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.enabled===false?'danger':'success'">{{ s.row.enabled===false?'停用':'启用' }}</el-tag></template></el-table-column></el-table></div><el-dialog title="新增平台用户" :visible.sync="dialog" width="460px"><el-form :model="form" label-width="90px"><el-form-item label="用户名"><el-input v-model="form.userName" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" show-password /></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></span></el-dialog></section></template>
<script>
import request from '@/utils/request'
import { createAdminUserApi } from '@/api/Match'
export default { data:()=>({loading:false,saving:false,dialog:false,users:[],keyword:'',form:{userName:'',password:''}}),computed:{filtered(){return this.users.filter(u=>!this.keyword||String(u.userName||u.username||'').toLowerCase().includes(this.keyword.toLowerCase()))}},created(){this.load()},methods:{async load(){this.loading=true;try{const r=await request.get('/admin/users');this.users=r.data||[]}finally{this.loading=false}},async create(){if(!this.form.userName||!this.form.password){this.$message.error('用户名和密码不能为空');return}this.saving=true;try{await createAdminUserApi(this.form);this.dialog=false;this.form={userName:'',password:''};this.$message.success('用户已创建');await this.load()}finally{this.saving=false}}} }
</script>
